insert into public.products (id,category_id,name,name_en,slug,description,description_en,sku,price,sale_price,images,stock_status,is_active,sort_order) values
('83dd94ea-edc7-4f07-83ec-390798288aab','80589292-7ecc-49ab-b2f1-31e1458cd6fd','אקסטרים - פסלון מדף','Extreme - Shelf Figurine','akstrym-pslvn-mdp-wo5ma9','<p class="ql-align-right">פסלון מתכת של רוכב סקייטבורד אקסטרים.</p><p class="ql-align-right">המוצר כולל בסיס דק שאינו נראה לעין המאפשר הצבתו על קצה מדף או מקום אחר, באופן המדמה את הסכנה האהובה על העוסקים בספורט אתגרי זה.</p>','<p class="ql-align-right">A metal figurine of an extreme skateboarder.</p><p class="ql-align-right">The product includes a thin base that is invisible to the eye, allowing it to be placed on the edge of a shelf or other location, simulating the beloved danger of those engaged in this challenging sport.</p>','AD294',69.90,NULL,ARRAY['assets/product-1773749683285-nwz7pw.webp','assets/product-1773749684320-myyh6.webp','assets/product-1773749685509-5imu0f.webp','assets/product-1773749686609-lnp5j.webp','assets/product-1773749687162-ujliiq.webp','assets/product-1773749688610-z92b2s.webp']::text[],'in_stock',true,0),
('037275e1-66f4-40c8-a5a3-465f1ad94d77','80f05cb9-f61d-4735-9634-74b879c88c17','רוני ומוטי שחקני מטקות - פסלון מדף דקורטיבי','Roni and Moti Matkot Players - Decorative Shelf Figurine','rvny-vmvty-shchkny-mtkvt-pslvn-mdp-dkvrtyby-mfa4z2','<p class="ql-align-right">מקורו של משחק המטקות אינו ידוע, אך הוא מאומץ מזה שנים רבות כמשחק המייצג יותר מכל את הישראלי הטיפוסי. המשחק משוחק בעיקר על חוף הים, בעיקר בחודשי הקיץ, על ידי שני משתתפים החובטים בכדור פלסטיק גמיש באמצעות מחבטי עץ עגולים. למשחק אין כמעט חוקים וכל שמוטל על המשתתפים הוא לדאוג לכך שהכדור לא ייפול לקרקע. במשחק אין מנצח או מפסיד (אולי פרט לאלו שהצליחו, או הצליחו פחות, להתחמק מכדור גומי טועה בראש...). פסלי המתכת של "ארטאורי דיזיין"&nbsp;מתארים מספר דמויות של שחקני מטקות ישראלים שהם לאו דווקא חטובי גוף. לשחקן הישראלי המצוי, עב הכרס, זו ככל הנראה הפעילות הספורטיבית היחידה עליה הוא אינו מוותר בין מנת אבטיח לג''חנון של שבת. הפסלים מקפיאים את הדמויות בתנועת משחק או מנוחה.</p>','<p class="ql-align-right">The origin of the matkot game is unknown, but it has been adopted for many years as the game that represents the typical Israeli more than any other. The game is played mainly on the beach, especially during the summer months, by two participants who hit a flexible plastic ball using round wooden paddles. The game has almost no rules and all that is required of the participants is to ensure that the ball does not fall to the ground. There is no winner or loser in the game (perhaps except for those who managed, or managed less, to dodge an errant rubber ball to the head...). The metal sculptures by "Artauri Design" depict several figures of Israeli matkot players who are not necessarily well-built. For the average Israeli player, with a thick belly, this is probably the only sporting activity he doesn''t give up between a watermelon slice and Saturday''s jachnun. The sculptures freeze the figures in a game movement or rest position.</p>','ma26',199.00,NULL,ARRAY['assets/product-1773749683054-i21fap.webp','assets/product-1773749684031-p8p0pr.webp','assets/product-1773749684484-9iwbpo.webp','assets/product-1773749685200-b45cys.webp','assets/product-1773749685817-qnn9xa.webp']::text[],'in_stock',true,0),
('fbb8739c-dde0-439b-832d-143aa89d2b3e','7c69abb4-9e5c-4be7-ae10-ca566cf2b3b3','זוג שחקני מטקות - פסלוני מדף דקורטיביים עשויים מתכת','Pair of Matkot Players - Decorative Metal Shelf Figurines','zvg-shchkny-mtkvt-pslvny-mdp-dkvrtybyym-ashvyym-mtkt-d64pru','<p class="ql-align-right">מקורו של משחק המטקות אינו ידוע, אך הוא מאומץ מזה שנים רבות כמשחק המייצג יותר מכל את הישראלי הטיפוסי. המשחק משוחק בעיקר על חוף הים, בעיקר בחודשי הקיץ, על ידי שני משתתפים החובטים בכדור פלסטיק גמיש באמצעות מחבטי עץ עגולים. למשחק אין כמעט חוקים וכל שמוטל על המשתתפים הוא לדאוג לכך שהכדור לא ייפול לקרקע. במשחק אין מנצח או מפסיד (אולי פרט לאלו שהצליחו, או הצליחו פחות, להתחמק מכדור גומי טועה בראש...). פסלוני המתכת של "ארטאורי דיזיין" מתארים מספר דמויות של שחקני מטקות ישראלים שהם לאו דווקא חטובי גוף. לשחקן הישראלי המצוי, עב הכרס, זו ככל הנראה הפעילות הספורטיבית היחידה עליה הוא אינו מוותר בין מנת אבטיח לג''חנון של שבת. הפסלים מקפיאים את הצלליות של הדמויות בתנועת משחק או מנוחה.</p><p>קישוט יפה למדף שמעורר ענין ומעלה חיוך.</p><p>מתנה מיוחדת לחנוכת בית, לחג, או מתנה לעצמך.</p><p>עשוי מתכת, צבע שחור.</p>','<p class="ql-align-right">The origin of the matkot game is unknown, but it has been adopted for many years as the game that represents the typical Israeli more than any other. The game is played mainly on the beach, especially during the summer months, by two participants hitting a flexible plastic ball with round wooden paddles. The game has almost no rules and all that is required of the participants is to ensure that the ball doesn''t fall to the ground. There is no winner or loser in the game (perhaps except for those who managed, or managed less, to dodge an errant rubber ball to the head...). The metal figurines by "Artauri Design" depict several figures of Israeli matkot players who are not necessarily athletic in build. For the average Israeli player, with a thick belly, this is probably the only sporting activity he doesn''t give up on between a watermelon slice and Saturday''s jachnun. The sculptures freeze the silhouettes of the figures in game motion or rest.</p><p>A beautiful shelf decoration that sparks interest and brings a smile.</p><p>A special gift for housewarming, holidays, or a gift for yourself.</p><p>Made of metal, black color.</p>','ma510',199.00,NULL,ARRAY['assets/product-1773749683043-75t7o.webp','assets/product-1773749683779-7lk0a.webp','assets/product-1773749684440-0wvsz.webp','assets/product-1773749685051-fyaik.webp']::text[],'in_stock',true,0),
('f8242daf-8036-4ee4-84ec-7030375de981','f646f62d-2bf6-4721-9020-141031e08ece','מתלה קולב','Hanger Hook','mtlh-kvlb-lyu04j','<p>מתלה מתכתי בצורת קולב בגדים מוקטן. מתלה מעוצב שישמש אתכם לתליית תיקים, תכשיטים, בגדים וחפצים שונים. המתלה עשוי ממתכת בצביעה איכותית בתנור. שימושי, מושך ענין ומוסיף סטייל לחדר.</p><p><strong>מידות</strong></p><p>גדול: אורך 16ס&quot;מ, רוחב 9.5ס&quot;מ, גובה 7ס&quot;מ</p><p>קטן: אורך 12ס&quot;מ, רוחב 7.5ס&quot;מ, גובה 7ס&quot;מ</p>','<p>A miniature clothes hanger-shaped metal hook. A decorative hanger designed to hold your bags, jewelry, clothes, and various items. The hanger is made of metal with a quality oven-baked finish. Practical, eye-catching, and adds style to any room.</p><p><strong>Dimensions</strong></p><p>Large: Length 16cm, Width 9.5cm, Height 7cm</p><p>Small: Length 12cm, Width 7.5cm, Height 7cm</p>','AD350',39.00,NULL,ARRAY['assets/product-1773749676979-g4596d.webp']::text[],'in_stock',true,0),
('b236507d-832b-46e6-b036-707869f01ef2','25f27ca0-db5c-478d-9381-32b42cdf1f61','סנאי מפצח אגוזים','Squirrel Nutcracker','snay-mptsch-agvzym-ma08cc','<p>סנאי מפצח אגוזים שדרגו את שולחן החג שלכם! מפצח אגוזים אלגנטי ופונקציונלי, מעוצב בצורת סנאי חמוד. מקורי ויפה, עשוי מתכת מבריקה בציפוי כרום ניקל. מתאים במיוחד כמתנה לחג הפסח! המוצר כולל סנאי חמוד ומגש קטן עם חורים ייעודיים לתצוגת שלושה אגוזים. הסנאי מפצח את האגוזים בסטייל באמצעות כפותיו, על ידי סיבובן בחריץ האגוז. עיצוב ייחודי, חגיגי ומרשים בצבע כסוף מבריק, מתאים להעמדה בסלון, על קומודה או על שולחן החג. מידות: גובה: 8 ס"מ, אורך: 8.5 ס"מ, רוחב: 5 ס"מ. משקל: 100 גר''.</p>','<p>Squirrel nutcracker that will upgrade your holiday table! An elegant and functional nutcracker, designed in the shape of a cute squirrel. Original and beautiful, made of shiny metal with chrome nickel plating. Especially suitable as a gift for Passover! The product includes a cute squirrel and a small tray with dedicated holes for displaying three nuts. The squirrel cracks the nuts in style using its paws, by rotating them in the nut groove. Unique, festive and impressive design in shiny silver color, suitable for placement in the living room, on a dresser or on the holiday table. Dimensions: Height: 8 cm, Length: 8.5 cm, Width: 5 cm. Weight: 100 grams.</p>','AD360',79.90,NULL,ARRAY['assets/product-1773749674206-gdghsp.webp','assets/product-1773749674756-9ourr.webp','assets/product-1773749675224-zkkqo4.webp','assets/product-1773749675791-12i2oh.webp']::text[],'in_stock',true,0),
('776b6bbf-4859-47c5-aa7a-644481cab718','19453142-9567-4420-ad4a-44f6b5a8c7ac','זוג תומכי ספרים לספרי בישול','Pair of Bookends for Cookbooks','zvg-tvmky-sprym-lspry-byshvl-7g5nzb','<p class="ql-align-right">תומכי ספרים ייחודיים, המיועדים לתמיכה של ספרי בישול. המוצר כולל שני תומכים, אחד עם דמות של שף והשני עם דמות של שפית.</p><p class="ql-align-right">המוצר עשוי ממתכת חזקה ומיועד להחזקת ספרים בישול.</p>','<p class="ql-align-right">Unique bookends designed to support cookbooks. The product includes two bookends, one featuring a chef figure and the other featuring a female chef figure.</p><p class="ql-align-right">The product is made of strong metal and is designed to hold cookbooks.</p>','AD285',109.00,NULL,ARRAY['assets/product-1773749660061-45meob.webp','assets/product-1773749660801-nw1h4.webp','assets/product-1773749661518-wmpgx.webp','assets/product-1773749662012-dq8o2d.webp','assets/product-1773749662609-th8qd5.webp','assets/product-1773749663348-7cym9f.webp']::text[],'in_stock',true,0),
('88f5a1cd-b79a-439f-8a8d-7fa04aed161b','25f27ca0-db5c-478d-9381-32b42cdf1f61','כלב טוב - מתקן לקיסמים','Good Dog - Toothpick Holder','klb-tvb-mtkn-lkysmym-1eoh9u','<p class="ql-align-right">מתקן שולחני לקיסמים מעוצב כמו גביע פרס עם כלב חמוד שמביא מקל. הקיסמים מאוחסנים בתוך מגירה קטנה בתחתית המוצר וקיסם אחד מונח בפיו של הכלב לתצוגה.</p><p class="ql-align-right">בעזרת ניעור קל יוצא קיסם מתוך חור בחזית המוצר. מתנה מקסימה לחובבי כלבים. קיים באפור אבן וברונזה.</p>','<p class="ql-align-right">A desktop toothpick holder designed like a trophy with a cute dog bringing a stick. The toothpicks are stored inside a small drawer at the bottom of the product and one toothpick is placed in the dog''s mouth for display.</p><p class="ql-align-right">With a gentle shake, a toothpick comes out through a hole in the front of the product. A charming gift for dog lovers. Available in stone gray and bronze.</p>','AD27..',39.89,NULL,ARRAY['assets/product-1774277529610-fkft5b.webp','assets/product-1773749649499-mom3em.webp','assets/product-1773749650002-sms0vr.webp','assets/product-1773749650546-3rvrh.webp','assets/product-1773749650937-f7bscc.webp','assets/product-1773749651484-xgtqhq.webp','assets/product-1773749651952-71yogq.webp','assets/product-1773749652470-glu6o.webp','assets/product-1773749652949-ta74v.webp','assets/product-1773749653363-r8acuh.webp','assets/product-1773749653763-p8wt5.webp','assets/product-1773749654187-39gm8.webp','assets/product-1773749654655-n4hr0n.webp','assets/product-1773749655078-huck17.webp','assets/product-1773749655741-0xr28gv.webp','assets/product-1773749656498-srjxg.webp','assets/product-1773749656916-wem76d.webp','assets/product-1773749657640-88sfom.webp','assets/product-1773749658066-gtdhz.webp']::text[],'in_stock',true,0),
('42dae9e7-6cb9-4927-a658-dd81dcc37fed','80589292-7ecc-49ab-b2f1-31e1458cd6fd','פקקופסא - קופסת אחסון לאמבטיה','Plugbox - Bathroom Storage Box','pkkvpsa-kvpst-achsvn-lambtyh-nueolv','<p><strong>פקקופסא - IN SINK</strong></p><p class="ql-align-right">מספריים, קוצץ ציפורניים, קסמי אוזניים, סיכות וגומיות לשיער - כל החפצים הקטנים האלה שצריך לאחסן בחדר הרחצה, עכשיו יש איפה!!</p><p>שדרגו את החלל עם סדר, ארגון ועיצוב יפה, נקי ומקורי.</p><p class="ql-align-right">כלי עגול מדליק, עשוי קרמיקה בצבע לבן ונקי, מעוצב בצורה של פקק אמבטיה, יעזור לך לארגן ולסדר את חדר הרחצה.</p><p class="ql-align-right">עשוי מקרמיקה עם שרשרת ברזל אלומיניום.</p><p>✨ <strong>עיצוב ייחודי ופרקטי:</strong></p><p>הקופסה מעוצבת בהשראת פקק אמבטיה, עם שרשרת אלומיניום שמוסיפה טאץ’ של מקוריות ואופי.</p><p>✨ <strong>איכות חומרים גבוהה:</strong></p><p>עשויה מקרמיקה איכותית ועמידה, שמבטיחה שימוש לאורך זמן ושומרת על מראה אלגנטי.</p><p>✨ <strong>ארגון וסדר:</strong></p><p>מתאימה לאחסון פריטים קטנים כמו קוצץ ציפורניים, צמר גפן, מקלות אוזניים ועוד – כל מה שצריך בהישג יד בחדר האמבטיה</p><p>✨ <strong>מתנה מושלמת:</strong></p><p>מתנה מקורית ומלאת סטייל למי שמעריך עיצוב מיוחד ואוהב חדר רחצה מאורגן.</p>','<p><strong>Plugbox - IN SINK</strong></p><p class="ql-align-right">Scissors, nail clippers, ear swabs, bobby pins, and hair ties - all those little items you need to store in the bathroom, now have a place!!</p><p>Upgrade your space with order, organization, and beautiful, clean, original design.</p><p class="ql-align-right">A stunning round vessel, made of white and clean ceramic, designed in the shape of a bathtub plug, will help you organize and tidy up your bathroom.</p><p class="ql-align-right">Made from ceramic with an aluminum chain.</p><p>✨ <strong>Unique and Practical Design:</strong></p><p>The box is designed inspired by a bathtub plug, with an aluminum chain that adds a touch of originality and character.</p><p>✨ <strong>High-Quality Materials:</strong></p><p>Made from quality and durable ceramic, ensuring long-term use while maintaining an elegant appearance.</p><p>✨ <strong>Organization and Order:</strong></p><p>Perfect for storing small items such as nail clippers, cotton wool, ear swabs, and more – everything you need within reach in the bathroom</p><p>✨ <strong>The Perfect Gift:</strong></p><p>An original and stylish gift for those who appreciate special design and love an organized bathroom.</p>','AD260',55.00,39.00,ARRAY['assets/product-1773749649903-cb5948.webp','assets/product-1773749650775-h9ayb6.webp','assets/product-1773749651203-rafaqh.webp','assets/product-1773749653509-7mukyz.webp','assets/product-1773749653945-um3w1s.webp','assets/product-1773749654347-uf1rnc.webp','assets/product-1773749654671-vqlrea.webp','assets/product-1773749655006-dbzgti.webp','assets/product-1773749655758-e1y4i.webp','assets/product-1773749656465-n1f5.webp']::text[],'in_stock',true,0),
('49e21dd7-917f-49ac-9858-1d023ddf37c4','e12fff82-e122-4b55-bf6b-c866c65cf858','סוף העיפרון - כוס לציוד משרדי','Pencil End Cup - Desk Organizer for Office Supplies','svp-hayprvn-kvs-ltsyvd-mshrdy-0383cb','<p class="ql-align-right">Pencil End Cup – סוף העיפרון</p><p class="ql-align-right">מעמד שולחני יפה ומעוצב לאחסון ציוד משרדי.</p><p class="ql-align-right">מעוצב כקצה של עיפרון עם מחק בצבע ורוד.</p><p class="ql-align-right">יחידה הכוללת שני כלי אחסון - החלק העליון לעטים, עפרונות, טושים, מספריים, והחלק התחתון לסיכות, גומיות, מחקים, מהדקים.</p><p class="ql-align-right">מידות – גובה: 14 ס&quot;מ, קוטר : 7 ס&quot;מ.</p><p class="ql-align-right">משקל: 80 גר&#39;</p><p class="ql-align-right">עשוי מתכת ופלסטיק</p><p>מסופק כרגע ללא אריזת מתנה</p>','<p class="ql-align-right">Pencil End Cup – סוף העיפרון</p><p class="ql-align-right">A beautiful and stylish desktop stand for storing office supplies.</p><p class="ql-align-right">Designed as the tip of a pencil with a pink eraser.</p><p class="ql-align-right">A unit that includes two storage compartments – the upper part for pens, pencils, markers, and scissors, and the lower part for pins, rubber bands, erasers, and clips.</p><p class="ql-align-right">Dimensions – Height: 14 cm, Diameter: 7 cm.</p><p class="ql-align-right">Weight: 80 g</p><p class="ql-align-right">Made of metal and plastic</p><p>Currently supplied without gift packaging</p>','AD243',49.90,NULL,ARRAY['assets/product-1773749649109-6xokoj.webp','assets/product-1773749650000-nxuq2p.webp','assets/product-1773749650643-ro7s5f.webp','assets/product-1773749652714-e1os2s.webp','assets/product-1773749653155-b76ac.webp','assets/product-1773749653533-yd1412.webp']::text[],'out_of_stock',true,0),
('3cd443e1-dc3f-4c65-a8a1-74979fe21d25','e12fff82-e122-4b55-bf6b-c866c65cf858','קלמחק - קלמר מעוצב כמחק','Pencil Case - Designer Pencil Case Shaped Like an Eraser','klmchk-klmr-mavtsb-kmchk-1h57oe','<p class="ql-align-right">קלמר מעוצב כמו מחק ענק. מתנה נהדרת לסטודנטים ותלמידים. עשוי מפלסטיק גמיש עם הדפסה. מידות 23X3X7 ס"מ.</p>','<p class="ql-align-right">A designer pencil case shaped like a giant eraser. A wonderful gift for students and pupils. Made of flexible plastic with printing. Dimensions 23X3X7 cm.</p>','AD252',55.00,NULL,ARRAY['assets/product-1773749649319-r6rat.webp','assets/product-1773749652377-fmawq.webp','assets/product-1773749653065-dbzrwg.webp','assets/product-1773749653665-6xfszf.webp']::text[],'in_stock',true,0),
('b28523da-cef5-487b-85e5-649a355b1159','e12fff82-e122-4b55-bf6b-c866c65cf858','מחק''ס - מחק מעוצב כמו נוזל מחיקה (טיפקס)','Erase-X - Designer Eraser Shaped Like Correction Fluid (Tipp-Ex)','mchks-mchk-mavtsb-kmv-nvzl-mchykh-typks-2xzoum','<p class="ql-align-right">מחק בצורה של טיפקס! כדי למחוק לא צריך לנער, לדלל או לחכות שיתייבש, פשוט למחוק!</p><p class="ql-align-right"><br></p><p>המחקX או Erase-X, מחק בצורת בקבוקון נוזל מחיקה קלאסי, שעושה כבוד למוצר הוותיק בטוויסט עיצובי חדש והומוריסטי. מחק-X נוח לשימוש ולאחיזה, מעניק שעות רבות של שימוש ותמיד משעשע! בלבלו את חבריכם ללימודים, הצחיקו את עמיתכם לעבודה והכי חשוב, העלו חיוך על שפתותיכם במהלך היום. מתנה מקסימה לתחילת שנת הלימודים לילדים, לנוער וגם לסטודנטים, ובכל עת לאמנים וליוצרים. סרטון הדגמה:</p>','<p class="ql-align-right">An eraser in the shape of Tipp-Ex! To erase, no need to shake, thin out, or wait for it to dry - just erase!</p><p class="ql-align-right"><br></p><p>The Erase-X, an eraser shaped like a classic correction fluid bottle, pays tribute to the vintage product with a new and humorous design twist. Erase-X is comfortable to use and hold, provides many hours of use and is always entertaining! Confuse your study buddies, amuse your work colleagues, and most importantly, bring a smile to your face throughout the day. A charming gift for the start of the school year for children, teens, and students, and anytime for artists and creators. Demo video:</p>','AD253',9.90,NULL,ARRAY['assets/product-1773749649315-g7hits.webp','assets/product-1773749649864-pyhpzc.webp','assets/product-1773749651358-mdwwsc.webp','assets/product-1773749652996-x1bqd.webp']::text[],'in_stock',true,0),
('776eab90-aaa2-48ea-969c-a1f2d0bd8432','7ea887fd-3cf5-4fa4-a8fd-a0c32560749b','שעון קיר - מפת ירושלים - אנגלית','Wall Clock - Jerusalem Map - English','shavn-kyr-mpt-yrvshlym-anglyt-pmsk2z','<p class="ql-align-right">שעון כיכר השעון - "טליתא קומי" ירושלים: אנגלית שעון קיר המתאר קטע ממפת מרכז ירושלים, כאשר מחוגי השעון ממוקמים בקרן הרחובות בן יהודה והמלך ג''ורג בכיכר המכונה כיכר "טליתא קומי". מקור השם, שתרגומו המילולי מארמית לעברית הוא "ילדה קטנה, קומי", נעוץ בסיפור מהברית החדשה המתאר נס שנעשה ע"י ישו, אשר גרם לילדה קטנה - בתו של יאיר הגלילי, לקום ולהלך, וזאת לאחר שחלתה ומתה. במקום שכן בעבר מבנה מפואר, ששימש בית יתומות וכלל בחזיתו קשתות, שלט הנושא את השם "טליתא קומי" ושעון גדול. המבנה נהרס עם השנים, אולם חזיתו ובה השעון, נותרו על תילם. הכיכר מפורסמת בירושלים גם היום כמקום מפגש ויציאה של צעירים לבילויים. קיים בעברית או אנגלית. עשוי מזכוכית מחוסמת וחזקה עם הדפסה אחורית איכותית ומבריקה. השעון כולל מנגנון שקט ורציף ונמכר באריזה מגינה ואיכותית. קוטר - 30 ס"מ.</p>','<p class="ql-align-right">Clock Square Clock - "Talitha Kumi" Jerusalem: English A wall clock depicting a section of central Jerusalem''s map, with the clock hands positioned at the intersection of Ben Yehuda and King George streets in the square known as "Talitha Kumi" Square. The name''s origin, whose literal translation from Aramaic to Hebrew is "little girl, arise," stems from a New Testament story describing a miracle performed by Jesus, who caused a little girl - the daughter of Jairus the Galilean, to rise and walk after she had fallen ill and died. The location once housed a magnificent building that served as an orphanage and featured arches on its facade, a sign bearing the name "Talitha Kumi" and a large clock. The building was demolished over the years, but its facade with the clock remained intact. The square is famous in Jerusalem even today as a meeting and departure point for young people going out for entertainment. Available in Hebrew or English. Made of tempered and strong glass with high-quality glossy back printing. The clock includes a quiet and continuous mechanism and is sold in protective and quality packaging. Diameter - 30 cm.</p>','AD226',99.00,NULL,ARRAY['assets/product-1773749645668-603vwl.webp','assets/product-1773749646820-b2sr1.webp','assets/product-1773749647524-awuixc.webp','assets/product-1773749648314-cffn5t.webp']::text[],'in_stock',true,0),
('2cae7d76-a9a7-4699-8bd1-541e36d57e66','7ea887fd-3cf5-4fa4-a8fd-a0c32560749b','שעון קיר - מפת יפו - אנגלית','Wall Clock - Jaffa Map - English','shavn-kyr-mpt-ypv-anglyt-re90us','<p class="ql-align-right">שעון כיכר השעון - יפו - אנגלית שעון קיר הכולל קטע מתוך מפת תל אביב יפו, באזור יפו העתיקה ובמרכזו מחוגים הממוקמים בדיוק בכיכר השעון. בשעון ניתן לראות את רחובות יפו העתיקה, שוק הפשפשים, טיילת יפו, הים וכיכר הסוכנות המכונה "כיכר השעון". מתנה מקורית לאורחים מחו"ל או לפטריוטים מקומיים. קיים בעברית או אנגלית. קוטר : 30 ס"מ. עשוי מזכוכית מחוסמת עם הדפסה אחורית איכותית ומבריקה. השעון כולל מנגנון שקט ורציף ונמכר באריזה איכותית ומגינה.</p>','<p class="ql-align-right">Clock Square Clock - Jaffa - English A wall clock featuring a section from the Tel Aviv-Jaffa map, in the Old Jaffa area with clock hands positioned exactly at Clock Square. The clock displays the streets of Old Jaffa, the Flea Market, Jaffa Promenade, the sea, and the Agency Square known as "Clock Square". An original gift for guests from abroad or local patriots. Available in Hebrew or English. Diameter: 30 cm. Made of tempered glass with high-quality glossy back printing. The clock includes a quiet and continuous mechanism and is sold in high-quality protective packaging.</p>','AD222',99.00,NULL,ARRAY['assets/product-1773749645595-7kzcr.webp','assets/product-1773749646168-5u70cy.webp','assets/product-1773749646760-bivalt.webp','assets/product-1773749647221-wxajc.webp']::text[],'in_stock',true,0),
('3b6e5495-647d-4654-9e6c-395e79ed8c4b','7ea887fd-3cf5-4fa4-a8fd-a0c32560749b','שעון קיר - מפת ירושלים - שער יפו','Wall Clock - Jerusalem Map - Jaffa Gate','shavn-kyr-mpt-yrvshlym-shar-ypv-d1rfnv','<p class="ql-align-right">שעון קיר המתאר קטע ממפת מרכז ירושלים, כאשר מחוגי השעון ממוקמים בשער יפו. מתנה מקורית לאורחים מחו"ל או לישראלים שגרים בחו"ל, או סתם לפטריוטים מקומיים. שעון איכותי עם מנגנון "סליפ" שקט ורציף.</p><p>עשוי עץ.</p><p class="ql-align-right">קוטר: 30 ס"מ משקל: 600 גר''</p>','<p class="ql-align-right">A wall clock depicting a section of central Jerusalem''s map, with the clock hands positioned at Jaffa Gate. An original gift for guests from abroad or Israelis living abroad, or simply for local patriots. High-quality clock with a quiet and continuous "slip" mechanism.</p><p>Made of wood.</p><p class="ql-align-right">Diameter: 30 cm Weight: 600 gr</p>','AD234',99.00,79.00,ARRAY['assets/product-1773749645593-ftwrpr6.webp']::text[],'out_of_stock',true,0),
('7e186811-260e-49fb-bcda-d2a34af710ed','e12fff82-e122-4b55-bf6b-c866c65cf858','נערת שער - מתקן לכרטיסי ביקור','Hair Girl - Business Card Holder','nart-shar-mtkn-lkrtysy-bykvr-l3o66z','<p class="ql-align-right">מעמד שולחני לכרטיסי ביקור הכולל שני מקומות להצגת הכרטיסים ומגש לכמות גדולה של כרטיסים. מתנה אידיאלית לאנשי עסקים.</p>','<p class="ql-align-right">Desktop stand for business cards that includes two places for displaying cards and a tray for a large quantity of cards. An ideal gift for business people.</p>','AD180',89.00,NULL,ARRAY['assets/product-1773749635821-ert0b.webp','assets/product-1773749642660-q56fbz.webp']::text[],'in_stock',true,0),
('f2fba736-c817-4f93-a5a0-8c6371ef3087','c4d77b37-fc91-4e2c-9a25-5419c13bdbc3','תחתית כיריים - מתכת','Stovetop Trivet - Metal','tchtyt-kyryym-mtkt-vz1gfz','<p class="ql-align-right">עיצוב המדמה כיריים, מאפשר הורדת הסיר מהכיריים והצבתו על השולחן, תוך הדמיית המשך הבישול... המוצר עשוי ברזל מגולוון וצבוע בצביעה איכותית בצבע שחור עם לקה מט.</p>','<p class="ql-align-right">Design that simulates a stovetop, allowing you to remove the pot from the stove and place it on the table, while creating the illusion that cooking continues... The product is made of galvanized iron and painted with high-quality black paint with a matte lacquer finish.</p>','AD189',99.00,NULL,ARRAY['assets/product-1773749636423-trxzdh.webp','assets/product-1773749639161-pdq33f.webp','assets/product-1773749639467-fsr6f.webp','assets/product-1773749638873-8h4a7b.webp','assets/product-1773749639947-67fzse.webp','assets/product-1773749637339-4g0gpm.webp','assets/product-1773749636011-kchh8g.webp']::text[],'in_stock',true,0),
('529b2d63-974c-4db5-9510-a04546d7bf6b','c4d77b37-fc91-4e2c-9a25-5419c13bdbc3','תחתית כיריים - סיליקון','Stovetop Trivet - Silicone','tchtyt-kyryym-sylykvn-mclumn','<p class="ql-align-right">עיצוב המדמה כיריים, מאפשר הורדת הסיר מהכיריים והצבתו על השולחן, תוך הדמיית המשך הבישול... המוצר עשוי סיליקון נמכר באריזת מתנה יוקרתית.</p>','<p class="ql-align-right">Design that mimics a stovetop, allows removing the pot from the burner and placing it on the table, while simulating the continuation of cooking... The product is made of silicone and sold in a luxurious gift box.</p>','AD188',55.00,NULL,ARRAY['assets/product-1773749636011-kchh8g.webp','assets/product-1773749636824-ux4jgc.webp','assets/product-1773749637339-4g0gpm.webp','assets/product-1773749636423-trxzdh.webp','assets/product-1773749637963-lvuw9r.webp','assets/product-1773749638536-ujqftv.webp','assets/product-1773749638873-8h4a7b.webp','assets/product-1773749639288-ycdgcqp.webp']::text[],'in_stock',true,0),
('72037048-f743-430d-8b03-00575dfbcece','99308e90-f80c-4e23-9611-1b61f0e2c0a5','בטיפול - כיסוי לקופסת טישו מרובעת','In Treatment - Square Tissue Box Cover','btypvl-kysvy-lkvpst-tyshv-mrvbat-9kd9n5','<p class="ql-align-right">כיסוי מעוצב לקופסת טישו סטנדרטית מרובעת. הכיסוי מונח על הקופסא ומתאר בצלליות סיטואציה מוכרת של טיפול פסיכולוגי, כאשר בין הפסיכולוג לפציאנט ממוקמת קופסת ממחטות נייר לעת הצורך... המוצר משתלב ומשדרג כל קופסת טישו מרובעת עשויה קרטון המונחת בבית או במשרד (או בקליניקה של הפסיכולוג). מתנה מלאת הומור למטפלים, מטופלים או סתם מצוננים... נמכר באריזת מתנה יוקרתית.</p><p class="ql-align-right">המוצר אינו כולל קופסת טישו.</p><p class="ql-align-right">מידות: גובה: 5 ס"מ, אורך: 11 ס"מ, עומק: 11 ס"מ . משקל: 140 גר''.</p>','<p class="ql-align-right">A designed cover for a standard square tissue box. The cover is placed on the box and depicts in silhouettes a familiar situation of psychological treatment, where a box of tissues is positioned between the psychologist and patient for when needed... The product integrates with and upgrades any square cardboard tissue box placed at home or in the office (or in the psychologist''s clinic). A humorous gift for therapists, patients, or just people with colds... Sold in premium gift packaging.</p><p class="ql-align-right">The product does not include a tissue box.</p><p class="ql-align-right">Dimensions: Height: 5 cm, Length: 11 cm, Depth: 11 cm. Weight: 140 gr.</p>','AD191',55.00,NULL,ARRAY['assets/product-1773749636213-pezaal.webp','assets/product-1773749636813-7xuflx.webp','assets/product-1773749637632-xfuxfa.webp','assets/product-1773749637998-u8i9n2.webp','assets/product-1773749638435-tvwbut.webp']::text[],'in_stock',true,0),
('cd9c6fb5-f816-4346-a42b-564623563364','25f27ca0-db5c-478d-9381-32b42cdf1f61','פלנקטון - מסננת פסטה או מסננת כללית למטבח - אדום','Plankton - Pasta Strainer or General Kitchen Strainer - Red','plnktvn-msnnt-psth-av-msnnt-kllyt-lmtbch-advm-odjwod','<p class="ql-align-right">לוויתן חביב שהוא בעצם כלי עזר שימושי מאוד במטבח. הכירו את פלנקטון, מסננת שעוזרת לסנן את המים ולהשאיר בסיר את מה שבישלתם. בין אם זה פסטה, ירקות מבושלים, פירות ים ועוד, המסננת תעזור להוציא את מי הבישול ולהשאיר את האוכל בפנים, ממש כמו שעושה הלוויתן כשהוא מזין את עצמו בפלנקטון מן הים.. המוצר מתאים לסירים בקוטר של 20-27 ס"מ, הוא קומפקטי ונוח לאחסון במגירת המטבח או תליה על מתלה, ניתן לניקוי בקלות (גם במדיח כלים). המוצר עשוי מפלסטיק קשיח שמתאים לטמפרטורות גבוהות.</p><p>מתנה מקסימה לחגים, לבית חדש, לבשלנים ולחובבי ים, חיות וליוויתנים...</p>','<p class="ql-align-right">A friendly whale that is actually a very useful kitchen tool. Meet Plankton, a strainer that helps filter water and keep what you''ve cooked in the pot. Whether it''s pasta, cooked vegetables, seafood and more, the strainer will help drain the cooking water and keep the food inside, just like a whale does when it feeds on plankton from the sea. The product fits pots with a diameter of 20-27 cm, it''s compact and convenient for storage in a kitchen drawer or hanging on a rack, easy to clean (dishwasher safe too). The product is made of hard plastic suitable for high temperatures.</p><p>A lovely gift for holidays, new home, cooks and lovers of sea, animals and whales...</p>','AD190',49.90,NULL,ARRAY['assets/product-1773749636022-rby6z.webp','assets/product-1773749636763-my8o7b.webp','assets/product-1774278074913-xfffx.webp','assets/product-1774278084815-f4c1vw.webp','assets/product-1774278145445-2dh9kc.webp']::text[],'in_stock',true,0),
('51645e93-0f44-45e8-871d-f36f256abc9f','41107b6e-2bae-4577-acd8-af98a10770fa','מציון פירמידה - מתקן למצות לחג הפסח מעוצב כפירמידה מצרית - צבע: כסף','Pyramid Matzah Holder - Passover Matzah Stand Designed as Egyptian Pyramid - Color: Silver','mtsyvn-pyrmydh-mtkn-lmtsvt-lchg-hpsch-mavtsb-kpyrmydh-mtsryt-tsba-ksp-mtzpyy','<p class="ql-align-right">מציון פירמידה: צבע כסף.</p><p class="ql-align-right">מתקן שולחני חגיגי למצות בצורת פירמידה הפוכה.</p><p class="ql-align-right">הפירמידות של מצרים כאחד מסמלי החג.</p><p class="ql-align-right">המתקן שישדרג לכם את שולחן חג הפסח ויעורר אצל אורחיכם התפעלות וענין.</p><p class="ql-align-right">המצות מוחזקות אנכית בתוך המתקן, על השולחן, מה שגם חוסך במקום על השולחן וגם מקנה עיצוב יפה ומיוחד.</p><p class="ql-align-right">צבעים: זהב וכסף.</p>','<p class="ql-align-right">Pyramid Matzah Holder: Silver color.</p><p class="ql-align-right">Festive tabletop matzah stand in the shape of an inverted pyramid.</p><p class="ql-align-right">The pyramids of Egypt as one of the symbols of the holiday.</p><p class="ql-align-right">The stand that will upgrade your Passover table and evoke admiration and interest among your guests.</p><p class="ql-align-right">The matzahs are held vertically within the stand, on the table, which both saves space on the table and provides beautiful and unique design.</p><p class="ql-align-right">Colors: Gold and Silver.</p>','AD157',139.00,NULL,ARRAY['assets/product-1773749627987-dfg74q.webp','assets/product-1773749628950-dwc9jm.webp','assets/product-1773749631280-dfixcg.webp','assets/product-1773749631849-lyk45c.webp','assets/product-1773749632380-a36hcf.webp']::text[],'in_stock',true,0),
('bf3d5a38-ff0b-4fcc-9131-5e3c9ccbda03','41107b6e-2bae-4577-acd8-af98a10770fa','מציון פירמידה - מתקן למצות לחג הפסח מעוצב כפירמידה מצרית - צבע: זהב','Pyramid Matzah Holder - Passover Matzah Stand Designed as Egyptian Pyramid - Color: Gold','mtsyvn-pyrmydh-mtkn-lmtsvt-lchg-hpsch-mavtsb-kpyrmydh-mtsryt-tsba-zhb-0qbdr3','<p class="ql-align-right">מציון פירמידה: צבע זהב.</p><p class="ql-align-right">מתקן שולחני חגיגי למצות בצורת פירמידה הפוכה.</p><p class="ql-align-right">הפירמידות של מצרים כאחד מסמלי החג.</p><p class="ql-align-right">המתקן שישדרג לכם את שולחן חג הפסח ויעורר אצל אורחיכם התפעלות וענין.</p><p class="ql-align-right">המצות מוחזקות אנכית בתוך המתקן, על השולחן, מה שגם חוסך במקום על השולחן וגם מקנה עיצוב יפה ומיוחד.</p><p class="ql-align-right">צבעים: זהב וכסף.</p>','<p class="ql-align-right">Pyramid Matzah Holder: Gold color.</p><p class="ql-align-right">Festive table stand for matzah in the shape of an inverted pyramid.</p><p class="ql-align-right">The pyramids of Egypt as one of the symbols of the holiday.</p><p class="ql-align-right">The stand that will upgrade your Passover table and evoke admiration and interest among your guests.</p><p class="ql-align-right">The matzah is held vertically within the stand, on the table, which both saves space on the table and provides a beautiful and unique design.</p><p class="ql-align-right">Colors: Gold and Silver.</p>','AD158',139.00,NULL,ARRAY['assets/product-1773749627979-iaigp.webp','assets/product-1773749629050-1hm9k.webp','assets/product-1773749629571-t75udb.webp','assets/product-1773749630055-aj3bk.webp','assets/product-1773749630589-abhg9f.webp','assets/product-1773749631105-jqqye8.webp','assets/product-1773749631664-yfp0q.webp']::text[],'in_stock',true,0),
('ffaca8f5-d523-433b-a95a-c4814720a1d2','ce5466ef-0dfb-4e8d-81f3-84791574cf8c','החתול והכלב - מעמד לנייר סופג - שחור','The Cat and Dog - Paper Towel Holder - Black','hchtvl-vhklb-mamd-lnyyr-svpg-shchvr-e29dzp','<p>Dog vs. Cat</p><p class="ql-align-right">מתקן מעוצב ומיוחד לגליל נייר סופג, המדמה סיטואציה של כלב מאוכזב המסתכל על חתול שברח וטיפס על גזע עץ. עשוי מתכת עמידה. צבע שחור.</p><p>פונקציונלי וגם יקשט לכם באלגנטיות את המטבח.</p>','<p>Dog vs. Cat</p><p class="ql-align-right">A designed and unique holder for paper towel rolls, depicting a situation of a disappointed dog looking at a cat that escaped and climbed up a tree trunk. Made of durable metal. Black color.</p><p>Functional and will also elegantly decorate your kitchen.</p>','AD161',159.90,NULL,ARRAY['assets/product-1773749627789-349m2o.webp','assets/product-1773749628554-uskjy.webp','assets/product-1773749629203-adgrzw.webp','assets/product-1773749629849-ez82st.webp','assets/product-1773749630476-ned2er.webp']::text[],'in_stock',true,0),
('26d431eb-e8fb-4652-82e8-8330f90d2d7b','ce5466ef-0dfb-4e8d-81f3-84791574cf8c','החתול והעורב - מעמד לנייר סופג - שחור','The Cat and the Raven - Paper Towel Holder - Black','hchtvl-vhavrb-mamd-lnyyr-svpg-shchvr-yiqyc8','<p><strong>החתול והעורב - מעמד לנייר סופג למטבח</strong></p><p>מתקן לגליל נייר סופג בעיצוב ייחודי שמספר סיפור קטן מהחיים - חתול דרוך אורב לעורב היושב על פנס רחוב, רגע אחד לפני מה שיכול לקרות (או לא לקרות).</p><p>העיצוב משלב הומור עדין עם דרמה מיניאטורית, והופך פריט יומיומי במטבח לאובייקט שמעורר חיוך ושיחה.</p><p><br></p><p>המתקן לא רק שימושי ונוח, אלא גם מוסיף טאץ’ אלגנטי עיצובי עם אופי, ומכניס למרחב רגע של דמיון, משחק והפתעה. מושלם לאוהבי עיצוב עם קריצה ולמי שמחפש פריטים קטנים עם נוכחות גדולה.</p><p class="ql-align-right"><br></p>','<p><strong>The Cat and the Raven - Kitchen Paper Towel Holder</strong></p><p>A paper towel roll holder with a unique design that tells a little story from life - a tense cat stalking a raven perched on a street lamp, one moment before what could happen (or not happen).</p><p>The design combines subtle humor with miniature drama, transforming an everyday kitchen item into an object that evokes smiles and conversation.</p><p><br></p><p>The holder is not only practical and convenient, but also adds an elegant design touch with character, bringing a moment of imagination, playfulness and surprise to the space. Perfect for design lovers with a wink and for those seeking small items with a big presence.</p><p class="ql-align-right"><br></p>','AD164',159.90,NULL,ARRAY['assets/product-1774449733306-d1hodh.webp','assets/product-1773749627792-f1m3k.webp','assets/product-1773749628839-qsqhzl.webp','assets/product-1773749629950-2a2jc.webp','assets/product-1774449699136-z6q5rh.webp','assets/product-1774449706471-9446i.webp','assets/product-1774449713625-456rkk.webp','assets/product-1774449720152-8h08r7.webp','assets/product-1774449726305-3t50i9.webp','assets/product-1774449797614-fxjpei.webp','assets/product-1774449802850-5qa3o.webp']::text[],'in_stock',true,0),
('8bd82504-d09e-482e-8b8c-2d0ba14c8297','99308e90-f80c-4e23-9611-1b61f0e2c0a5','בטיפול - כיסוי לקופסת טישו מלבנית','In Treatment - Rectangular Tissue Box Cover','btypvl-kysvy-lkvpst-tyshv-mlbnyt-85qkaa','<p class="ql-align-right">כיסוי מעוצב לקופסת טישו בגודל סטנדרטי. הכיסוי מונח על הקופסא ומתאר בצלליות סיטואציה של טיפול פסיכולוגי, כאשר בין הפסיכולוג לפציאנט, ממחטת נייר לעת הצורך... המוצר משתלב ומשדרג כל קופסת טישו עשויה קרטון המונחת בבית או במשרד (או בחדרו של הפסיכולוג). המוצר עשוי מאלומיניום כך שאינו מכביד על קופסת הטישו. מתנה עם הומור למטפלים, מטופלים או סתם מצוננים... נמכר באריזת מתנה יוקרתית ללא קופסת טישו. מידות: גובה: 19 ס"מ, אורך: 11 ס"מ, עומק: 9 ס"מ . משקל: 220 גר''.</p>','<p class="ql-align-right">A designer cover for standard-size tissue boxes. The cover sits on top of the box and depicts in silhouettes a psychological therapy situation, where between the psychologist and patient, tissues are within reach when needed... The product integrates with and upgrades any cardboard tissue box placed at home or in the office (or in the psychologist''s room). The product is made of aluminum so it doesn''t weigh down the tissue box. A humorous gift for therapists, patients, or just people with colds... Sold in luxury gift packaging without tissue box. Dimensions: Height: 19 cm, Length: 11 cm, Depth: 9 cm. Weight: 220 grams.</p>','AD160',109.00,NULL,ARRAY['assets/product-1773749627789-3vhige.webp','assets/product-1773749628182-gfetwm.webp','assets/product-1773749628841-y6ue5.webp','assets/product-1773749629254-zjw9u4.webp','assets/product-1773749629774-ln7hhk.webp']::text[],'in_stock',true,0),
('2ff8bd54-6c79-4633-bffa-bf33bded41e4','19453142-9567-4420-ad4a-44f6b5a8c7ac','תומך ספרים מעוצב ״מתגונן״ - Falling Bookend - לעיצוב וקישוט מדף הספרים','Designer Bookend "Defender" - Falling Bookend - For Decorating and Styling Your Bookshelf','tvmk-sprym-mavtsb-mtgvnn-falling-bookend-laytsvb-vkyshvt-mdp-hsprym-jgm00a','<p><strong>קסם על המדף!</strong></p><p>תומך ספרים ״מתגונן״ הוא פריט עיצובי ייחודי שמשלב פונקציונליות עם דרמה והומור. דופן התומך נכנסת אל תוך כריכת הספר והספרים נתמכים בזווית אלכסונית שיוצרת עניין על מדף הספרים.</p><p>מעבר להיותו תומך ספרים יציב וחזק, הוא הופך כל מדף סטנדרטי לפינה מעוצבת ומלאת השראה. מושלם לחדר ילדים, לחדר עבודה, לסלון או למשרד - לכל מי שאוהב ספרים וגם עיצוב עם קריצה.</p><p>העיצוב המינימליסטי והחכם מוסיף טאץ’ שובב ומקורי לחלל ומעניק אשליה שהגיבור מושיט את ידיו בהתגוננות מפני מפולת הספרים שמאיימת ליפול עליו ולמחוץ אותו.</p><p>מתנה נהדרת לאוהבי ספרים ולכל מי שמחפש פריט דקורטיבי יוצא דופן.</p><p><br></p><p>סרטון הדגמה</p>','<p><strong>Magic on the shelf!</strong></p><p>The "Defender" bookend is a unique design item that combines functionality with drama and humor. The bookend''s side enters into the book cover and the books are supported at a diagonal angle that creates interest on the bookshelf.</p><p>Beyond being a stable and strong bookend, it transforms any standard shelf into a designed corner full of inspiration. Perfect for a children''s room, study, living room or office - for anyone who loves books and also design with a wink.</p><p>The minimalist and clever design adds a playful and original touch to the space and creates an illusion that the hero is extending his hands defensively against the avalanche of books threatening to fall on him and crush him.</p><p>A wonderful gift for book lovers and anyone looking for an extraordinary decorative item.</p><p><br></p><p>Demonstration video</p>','AD100',99.00,NULL,ARRAY['assets/product-1773749608478-x12qhs.webp','assets/product-1773749609155-moqtt.webp','assets/product-1773749610144-nlzsfb.webp','assets/product-1773749610754-ccrm6z.webp','assets/product-1773749611576-gqtcj9.webp','assets/product-1773749619352-1zg7pg.webp','assets/product-1773749620339-b1bfsl.webp','assets/product-1773749620908-niv611v.webp','assets/product-1773749621549-83h53q.webp','assets/product-1773749622357-mimw6y.webp','assets/product-1773749622888-ro4g17.webp','assets/product-1773749623498-xf8qu4.webp','assets/product-1773749625100-2thfo9.webp','assets/product-1773749625958-yp0ha.webp','assets/product-1773749626354-k71z1r.webp','assets/product-1773749626673-ezkbt9.webp']::text[],'in_stock',true,0),
('4af93c52-625b-4d72-a430-a35d2471c8ea','721ba84f-bcbc-4975-96ea-c7af858e847c','סופרשלף - מדף ספרים צף בעיצוב גיבור על - מדף דקורטיבי לחלל המגורים, חלל העבודה או חדר הילדים','Supershelf - Floating Bookshelf in a Superhero Design - Decorative Shelf for the Living Space, Workspace, or Children''s Room','svprshlp-mdp-sprym-tsp-baytsvb-gybvr-al-mdp-dkvrtyby-lchll-hmgvrym-chll-habvdh-av-chdr-hyldym-zunto9','<p class="ql-align-right">Supershelf מדף ספרים שמדמה גיבור על שמחזיק ספרים שכאילו צפים באויר. עוד מוצר המשך של תומך הספרים הנופלים. מתנה מיוחדת ופרקטית לעיצוב הבית.</p><p>הוראות: - בחרו מקום והתקינו את המדף לקיר באמצעות שני ברגים . - הכניסו את בסיס המדף בין כריכת הספר (כריכה רכה) לעמוד הראשון (או האחרון). - הצמידו את היד המגנטית של גיבור העל עד להידוק הכריכה והצמדתה למדף. - הוסיפו ספרים עד למילוי כל גובה המדף. אריזה: נמכר באריזת מתנה צבעונית, שטוחה וחוסכת מקום. https://www.youtube.com/watch?v=0O7nH1TEv9Q </p>','<p class="ql-align-right">Supershelf is a bookshelf that simulates a superhero holding books that appear to float in the air. Another follow-up product to the falling bookend. A special and practical gift for home décor.</p><p>Instructions: - Choose a spot and mount the shelf to the wall using two screws. - Insert the shelf base between the book cover (soft cover) and the first (or last) page. - Attach the superhero''s magnetic hand until the cover is secured and fastened to the shelf. - Add books until the entire height of the shelf is filled. Packaging: Sold in a colorful, flat, space-saving gift box. https://www.youtube.com/watch?v=0O7nH1TEv9Q </p>','AD102',109.00,NULL,ARRAY['assets/product-1773749608836-f0wqwj.webp','assets/product-1773749609734-efgh2.webp','assets/product-1773749611038-66kow.webp','assets/product-1773749611778-vx958a.webp','assets/product-1773749612533-le7rlr.webp','assets/product-1773749614232-ps48.webp','assets/product-1773749615107-8qcbis.webp','assets/product-1773749615834-881r6l.webp','assets/product-1773749616475-w97dsr.webp','assets/product-1773749617204-jtq1pw.webp','assets/product-1773749617755-2v01fn.webp','assets/product-1773749618541-i7zixt.webp','assets/product-1773749619064-d018y.webp','assets/product-1773749619600-zh99ba.webp','assets/product-1773749620168-msgmrq.webp','assets/product-1773749620532-rhen1d.webp','assets/product-1773749621332-3hmd8l.webp']::text[],'in_stock',true,0),
('de7b5f92-d99d-4578-9524-98bd87f4216c','19453142-9567-4420-ad4a-44f6b5a8c7ac','תומך ספרים גיבור על - מעמד דקורטיבי לספרים למדף, לספריה או לשולחן העבודה','Superhero Bookend - Decorative Book Stand for Shelf, Library or Desk','tvmk-sprym-gybvr-al-mamd-dkvrtyby-lsprym-lmdp-lspryh-av-lshvlchn-habvdh-snqu3f','<p class="ql-align-right">תומך ספרים "גיבור על" Book&amp;Hero מתקן לספרים, ייחודי ומלא אופי, לקישוט הספריה או מדף הספרים.</p><p class="ql-align-right">מחזיק הספרים תומך את הספרים בזווית אלכסונית מפתיעה, יוצר אשליה של רגע לפני נפילה ואז, כמו משום מקום, מגיח גיבור על ותומך את הספרים שלא יפלו. מתנה מקורית לאוהבי ספרים (או גיבורי על או שניהם...) שיוצרת עניין על המדף ומעלה חיוך.</p><p>העיצוב יוצר תחושת תנועה ודרמה על המדף, מושך את העין ומעלה חיוך.</p><p>פריט דקורטיבי שמוסיף עניין, שובבות, עוצמה ואופי לכל ספרייה, משרד או חדר ילדים.</p><p>הוראות: - הכנסו את דופן התומך בין כריכת הספר (כריכה רכה) לדף הראשון (או האחרון). - השעינו ספרים נוספים על הספר עד למילוי כל שטח בסיס התומך. - הצמידו את היד המגנטית של גיבור העל עד להידוק הכריכה. - ניתן להשעין ספרים נוספים על הספרים המצויים על התומך. מידות: גובה 20 ס"מ, רוחב 12 ס"מ אורך 17 ס"מ. צבע: שחור. משקל: 350 גרם. חומר: ברזל בצביעה בתנור. כולל מגנט חזק. https://www.youtube.com/watch?v=yOQDfRdeO48&nbsp;&nbsp;</p>','<p class="ql-align-right">"Superhero" Book&Hero bookend - a unique and characterful book holder for decorating your library or bookshelf.</p><p class="ql-align-right">The bookend supports books at a surprising diagonal angle, creating an illusion of a moment before falling and then, as if from nowhere, a superhero emerges and supports the books so they don''t fall. An original gift for book lovers (or superhero fans or both...) that creates interest on the shelf and brings a smile.</p><p>The design creates a sense of movement and drama on the shelf, catches the eye and brings a smile.</p><p>A decorative item that adds interest, playfulness, power and character to any library, office or children''s room.</p><p>Instructions: - Insert the support side between the book cover (soft cover) and the first (or last) page. - Lean additional books against the book until the entire base area of the support is filled. - Attach the superhero''s magnetic hand until the cover is tightly secured. - Additional books can be leaned against the books on the support. Dimensions: height 20 cm, width 12 cm, length 17 cm. Color: black. Weight: 350 grams. Material: iron with oven paint finish. Includes strong magnet. https://www.youtube.com/watch?v=yOQDfRdeO48&nbsp;&nbsp;</p>','AD101',109.00,NULL,ARRAY['assets/product-1773749608215-ajx892.webp','assets/product-1773749608948-wtyxgg.webp','assets/product-1773749610728-c5rwel.webp','assets/product-1773749611763-4x1oll.webp','assets/product-1773749612564-p241e.webp','assets/product-1773749613559-fw7w6.webp','assets/product-1773749614669-4n4kxc.webp','assets/product-1773749615470-a0iwu.webp','assets/product-1773749616083-td9klg.webp','assets/product-1773749616556-9bgzzc.webp']::text[],'in_stock',true,0),
('a2d0e53d-b26e-432d-99e2-28193ea1ab09','61e54c0d-e01d-40d1-bf37-89dca2a7aec9','זוג יונים - פסלוני יונים לקישוט מדף - מתנה מיוחדת ורומנטית לעיצוב הבית','A Pair of Doves - Decorative Dove Figurines for Shelf Display - A Special and Romantic Gift for Home Décor','zvg-yvnym-pslvny-yvnym-lkyshvt-mdp-mtnh-myvchdt-vrvmntyt-laytsvb-hbyt-hy8y3y','<p>LOVEBIRDS - זוג יונים</p><p><strong>זוג פסלונים דקורטיביים מעוצבים כצלליות של ציפורים, עשויים מתכת איכותית בגימור מאט. </strong>צמד יונים היושבות על קצה מדף ומביטות זו בזו.</p><p>עיצוב נקי ואלגנטי המוסיף טאץ׳ של רומנטיקה והרמוניה לכל חלל.</p><p>✨ <strong>פריט דקורטיבי מרגש:</strong></p><p>עיצוב מלא משמעות של אהבה, חיבור ואינטימיות, מתאים לחלל המגורים או לחדר השינה.</p><p>✨ <strong>מתנה רומנטית מושלמת:</strong></p><p>מתנה אידיאלית לחנוכת בית, ימי נישואין, חג האהבה או Valentine’s Day – תשומת לב מקורית למי שיקר לכם באמת. מתנה לזוג, מתנה לבן / בת הזוג.</p><p>✨ <strong>איכות ויוקרה:</strong></p><p>מגיע באריזת מתנה מעוצבת ומרשימה, שתהפוך את החוויה למושלמת מהשנייה הראשונה.</p>','<p>LOVEBIRDS - A Pair of Doves</p><p><strong>A pair of decorative figurines designed as bird silhouettes, crafted from quality metal with a matte finish. </strong>Two doves perched on the edge of a shelf, gazing at one another.</p><p>A clean and elegant design that adds a touch of romance and harmony to any space.</p><p>✨ <strong>A Touching Decorative Piece:</strong></p><p>A design full of meaning — love, connection, and intimacy — perfect for the living room or bedroom.</p><p>✨ <strong>The Perfect Romantic Gift:</strong></p><p>An ideal gift for a housewarming, anniversary, Valentine''s Day, or any occasion — a truly original gesture for someone you deeply cherish. A gift for couples, a gift for a partner.</p><p>✨ <strong>Quality and Luxury:</strong></p><p>Arrives in a beautifully designed and impressive gift box, making the experience perfect from the very first moment.</p>','AD140',149.00,NULL,ARRAY['assets/product-1773749608176-c0oty.webp','assets/product-17